INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PRIDT0700000000000000000', '*', '', 'pri_report_card', 'Bulletin trimestriel (primaire)', 'bulletin', 'B', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 1, '["class_name","level_name","academic_year","period_label","average_line","rank_line","appraisal","conduct","absences","unjustified_absences","lates","decision","repeater","subjects_block","competencies_block","remediation_block","scale_legend"]', '2026-10-23T14:00:00+01:00', '2026-10-23T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT07F0000000000000000', '*', '', 'pri_report_card', 'fr', '<html><body style="font-size: 11px"><h1 style="font-size: 16px">{{establishment_name}}</h1><h2 style="font-size: 14px">Bulletin de notes · {{period_label}} · {{academic_year}}</h2><p>Élève : <strong>{{holder_name}}</strong> · Classe : {{class_name}} ({{level_name}}) {{repeater}}</p><p>{{average_line}} {{rank_line}}</p><h3 style="font-size: 12px">Matières</h3><div style="white-space: pre-line">{{subjects_block}}</div><h3 style="font-size: 12px">Compétences</h3><div style="white-space: pre-line">{{competencies_block}}</div><p style="font-size: 9px">{{scale_legend}}</p><h3 style="font-size: 12px">Assiduité et conduite</h3><p>Absences : {{absences}} demi-journée(s), dont {{unjustified_absences}} non justifiée(s) · Retards : {{lates}} · Conduite : {{conduct}}</p><h3 style="font-size: 12px">Remédiation</h3><div style="white-space: pre-line">{{remediation_block}}</div><p>Appréciation : {{appraisal}}</p><p>Décision du conseil : <strong>{{decision}}</strong></p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p style="font-size: 9px">Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T14:00:00+01:00', NULL, '2026-10-23T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT07E0000000000000000', '*', '', 'pri_report_card', 'en', '<html><body style="font-size: 11px"><h1 style="font-size: 16px">{{establishment_name}}</h1><h2 style="font-size: 14px">Report card · {{period_label}} · {{academic_year}}</h2><p>Pupil: <strong>{{holder_name}}</strong> · Class: {{class_name}} ({{level_name}}) {{repeater}}</p><p>{{average_line}} {{rank_line}}</p><h3 style="font-size: 12px">Subjects</h3><div style="white-space: pre-line">{{subjects_block}}</div><h3 style="font-size: 12px">Competencies</h3><div style="white-space: pre-line">{{competencies_block}}</div><p style="font-size: 9px">{{scale_legend}}</p><h3 style="font-size: 12px">Attendance and conduct</h3><p>Absences: {{absences}} half-day(s), {{unjustified_absences}} unexcused · Late arrivals: {{lates}} · Conduct: {{conduct}}</p><h3 style="font-size: 12px">Remediation</h3><div style="white-space: pre-line">{{remediation_block}}</div><p>Remarks: {{appraisal}}</p><p>Staff meeting decision: <strong>{{decision}}</strong></p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p style="font-size: 9px">Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T14:00:00+01:00', NULL, '2026-10-23T14:00:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PRIDT0800000000000000000', '*', '', 'pri_annual_report', 'Récapitulatif annuel (primaire)', 'bulletin', 'R', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 1, '["class_name","level_name","academic_year","terms_block","annual_average_line","rank_line","decision","appraisal","absences","remediation_block"]', '2026-10-23T14:00:00+01:00', '2026-10-23T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT08F0000000000000000', '*', '', 'pri_annual_report', 'fr', '<html><body style="font-size: 11px"><h1 style="font-size: 16px">{{establishment_name}}</h1><h2 style="font-size: 14px">Récapitulatif annuel · {{academic_year}}</h2><p>Élève : <strong>{{holder_name}}</strong> · Classe : {{class_name}} ({{level_name}})</p><h3 style="font-size: 12px">Trimestres</h3><div style="white-space: pre-line">{{terms_block}}</div><p>{{annual_average_line}} {{rank_line}}</p><p>Absences de l’année : {{absences}} demi-journée(s)</p><div style="white-space: pre-line">{{remediation_block}}</div><p>Appréciation : {{appraisal}}</p><p>Décision de fin d’année : <strong>{{decision}}</strong></p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p style="font-size: 9px">Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T14:00:00+01:00', NULL, '2026-10-23T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT08E0000000000000000', '*', '', 'pri_annual_report', 'en', '<html><body style="font-size: 11px"><h1 style="font-size: 16px">{{establishment_name}}</h1><h2 style="font-size: 14px">Annual summary · {{academic_year}}</h2><p>Pupil: <strong>{{holder_name}}</strong> · Class: {{class_name}} ({{level_name}})</p><h3 style="font-size: 12px">Terms</h3><div style="white-space: pre-line">{{terms_block}}</div><p>{{annual_average_line}} {{rank_line}}</p><p>Absences this year: {{absences}} half-day(s)</p><div style="white-space: pre-line">{{remediation_block}}</div><p>Remarks: {{appraisal}}</p><p>End-of-year decision: <strong>{{decision}}</strong></p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p style="font-size: 9px">Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T14:00:00+01:00', NULL, '2026-10-23T14:00:00+01:00');
